Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='designsystem', at=datetime(2026, 10, 4, 0, 0, 0), actor='owner', title="The look is the owner's design system, the typst-design package; no second definition of a colour, mark or template", body="*The look is the owner's design system* (2026-10-04): the public Typst package typst-design (`@local/typst-design`, a flake input on every shell's `TYPST_PACKAGE_PATH`, bundled for the tab as `typst/packages.json` by `scripts/typst-packages.mjs`). The site and the guide open with its `working-document`, the kit draws its `pie` and `fulfillment-color`, and `tokens.typ` names each app colour role as a sample of its ramps, from which `scripts/gen-tokens.mjs` prints `tokens.css` and `tokens.ts`. No second definition of a colour, mark or template is kept here; HTML pages carry classes, not colours, and the answer preamble is the package's names drawn with typst's own elements, since HTML export drops its shapes.", rationale='Decided 2026-10-04.', supersedes=()))